// Lightweight, dependency-free i18n dictionary. No next-intl/react-i18next —
// just a flat key -> string map per locale, looked up through t() (see
// language-context.tsx). Deliberately scoped: this translates UI chrome
// (navigation, headings, buttons, help text, disclaimers) into 11 Indian
// languages plus English, not the underlying data. Two things are
// intentionally left in English everywhere, in every locale:
//
//  1. Scheme data itself (name/ministry/summary/benefit/documents/steps —
//     data/schemes.ts). Machine-translating official scheme names and
//     government terminology risks distorting meaning; a real translation
//     would need to be sourced from each scheme's own official Hindi
//     materials, which is out of scope for this pass.
//  2. Assessment dropdown OPTION values (state names, category codes like
//     "OBC"/"SC"/"ST", sector names, business type, etc. — the *_OPTIONS
//     arrays in lib/matching/types.ts) and the matching engine's generated
//     criterion labels (lib/matching/engine.ts, frozen — no logic changes
//     this pass). These are shared, matched-against values; translating
//     only their on-screen label without touching the engine that
//     generates "Your sector (Technology) is supported"-style explanations
//     would leave the UI half-English anyway, so field LABELS are
//     translated but the option values themselves are not.
//
// Every other string a user reads — field labels, buttons, step titles,
// disclaimers, empty states — is fully translated.
//
// Translation quality note: the Hindi dictionary was written and reviewed
// by hand. The other ten (Bengali, Marathi, Telugu, Tamil, Gujarati,
// Kannada, Punjabi, Odia, Malayalam, Assamese) were AI-generated in one
// pass for this prototype — a real deployment should have a native speaker
// of each review them before going live, the same way scheme facts
// themselves need official verification (see the disclaimer banner).
// Machine translation is a reasonable way to demonstrate breadth of
// language support; it isn't a substitute for a native reviewer on a
// government-facing product.

export type Locale = 'en' | 'hi' | 'bn' | 'mr' | 'te' | 'ta' | 'gu' | 'kn' | 'pa' | 'or' | 'ml' | 'as'

// Language selection: English + 11 of the most-spoken scheduled languages
// of India by first-language speaker count (2011 Census — the most recent
// completed census), restricted to left-to-right Brahmic scripts. Together
// these 12 languages cover the large majority of India's population as a
// first language. Urdu (#7 by speaker count, ~4.2%) is the one scheduled
// language deliberately still deferred — not because it matters less, but
// because it's written right-to-left and would need a real RTL layout pass
// (logical-property spacing, mirrored icons, `dir` switching) across the
// whole app — doing that properly is future work, not something to bolt on
// in a pass without risking the rest of the UI. See the note above on
// translation quality for the same honesty applied to accuracy.
export const LOCALES: { code: Locale; label: string; nativeLabel: string; shortLabel: string }[] = [
  { code: 'en', label: 'English', nativeLabel: 'English', shortLabel: 'EN' },
  { code: 'hi', label: 'Hindi', nativeLabel: 'हिन्दी', shortLabel: 'हि' },
  { code: 'bn', label: 'Bengali', nativeLabel: 'বাংলা', shortLabel: 'বাং' },
  { code: 'mr', label: 'Marathi', nativeLabel: 'मराठी', shortLabel: 'मर' },
  { code: 'te', label: 'Telugu', nativeLabel: 'తెలుగు', shortLabel: 'తె' },
  { code: 'ta', label: 'Tamil', nativeLabel: 'தமிழ்', shortLabel: 'த' },
  { code: 'gu', label: 'Gujarati', nativeLabel: 'ગુજરાતી', shortLabel: 'ગુ' },
  { code: 'kn', label: 'Kannada', nativeLabel: 'ಕನ್ನಡ', shortLabel: 'ಕ' },
  { code: 'pa', label: 'Punjabi', nativeLabel: 'ਪੰਜਾਬੀ', shortLabel: 'ਪੰ' },
  { code: 'or', label: 'Odia', nativeLabel: 'ଓଡ଼ିଆ', shortLabel: 'ଓଡ଼' },
  { code: 'ml', label: 'Malayalam', nativeLabel: 'മലയാളം', shortLabel: 'മല' },
  { code: 'as', label: 'Assamese', nativeLabel: 'অসমীয়া', shortLabel: 'অস' },
]

