  'landing.whyEyebrow': 'स्कीमसेतु क्यों',
  'landing.whyTitle': 'एक काम के लिए बनाया गया, हर योजना के लिए नहीं',
  'landing.whySubtitle': 'एक केंद्रीय सरकारी पोर्टल पहले से ही हज़ारों योजनाएं सूचीबद्ध करता है। स्कीमसेतु उसकी जगह लेने की कोशिश नहीं करता — यह वह एक काम करता है जो एक सूची नहीं कर सकती: यह बताना कि कोई खास योजना आप पर क्यों लागू होती है या नहीं।',
  'landing.why1Title': 'स्कोर जो खुद को समझाते हैं',
  'landing.why1Desc': 'हर मैच बताता है कि कौन से मापदंड पूरे हुए, कौन से छूट गए, और कौन से असफल रहे — श्रेणी, लिंग, राज्य, क्षेत्र, कारोबारी चरण, पहली बार उद्यमी होने की स्थिति, और आय — न कि सिर्फ सूची में एक नाम।',
  'landing.why2Title': 'एक गाइडेड रास्ता, सर्च बॉक्स नहीं',
  'landing.why2Desc': 'एक छोटा मूल्यांकन आपकी स्थिति को एक बार समझता है, फिर हर योजना को उसके आधार पर रैंक करता है — बजाय इसके कि आपको पहले से पता हो कि हज़ारों में से किसे देखना है।',
  'landing.why3Title': 'आपके कारोबार के इर्द-गिर्द बनाया गया, सिर्फ आपकी पहचान के आधार पर नहीं',
  'landing.why3Desc': 'मैच आपके कारोबारी क्षेत्र, चरण, और पहली बार उद्यमी होने की स्थिति को भी तौलते हैं — न कि सिर्फ जनसांख्यिकीय पात्रता — ताकि नतीजे यह दिखाएं कि आपका उद्यम वास्तव में कहां खड़ा है।',
  'landing.why4Title': 'इंटरनेट के बिना भी काम करता है',
  'landing.why4Desc': 'ऐप के रूप में इंस्टॉल किया जा सकता है और ऑफलाइन उपयोग के लिए सेव रहता है, ताकि सेव किया गया मूल्यांकन और देखी गई योजनाएं बिना सिग्नल के भी उपलब्ध रहें।',
  'landing.why5Title': '12 भारतीय भाषाओं में, पूरी तरह से',
  'landing.why5Desc': 'पूरा मूल्यांकन, नतीजे, और स्पष्टीकरण अनुवादित हैं — न कि सिर्फ पेज के शीर्षक और बटन।',
  'landing.whyHonestNote': 'स्कीमसेतु फिलहाल {count} हाथ से सत्यापित योजनाओं को कवर करता है — सरकार के अपने पोर्टल पर मौजूद हज़ारों का एक छोटा हिस्सा। यह एक सोचा-समझा समझौता है: यहां हर योजना को बड़े पैमाने पर इकट्ठा करने के बजाय एक वास्तविक आधिकारिक स्रोत से अलग-अलग जांचा गया है। फिलहाल, चौड़ाई से ज़्यादा गहराई।',

