  'landing.whySubtitle': 'একটি কেন্দ্রীয় সরকারি পোর্টাল ইতিমধ্যেই হাজার হাজার প্রকল্প তালিকাভুক্ত করে। স্কিমসেতু সেটির জায়গা নেওয়ার চেষ্টা করে না — এটি এমন একটি কাজ করে যা একটি তালিকা করতে পারে না: একটি নির্দিষ্ট প্রকল্প কেন আপনার জন্য উপযুক্ত বা নয়, তা সঠিকভাবে দেখানো।',
