  'landing.why1Desc': 'প্রতিটি ম্যাচ দেখায় ঠিক কোন মানদণ্ড পূরণ হয়েছে, বাদ পড়েছে, বা ব্যর্থ হয়েছে — বিভাগ, লিঙ্গ, রাজ্য, ক্ষেত্র, ব্যবসার পর্যায়, প্রথমবার উদ্যোক্তা হওয়ার অবস্থা, এবং আয় — শুধু তালিকায় একটি নাম নয়।',
  'landing.why2Title': 'একটি গাইডেড পথ, সার্চ বক্স নয়',
  'landing.why2Desc': 'একটি ছোট মূল্যায়ন আপনার পরিস্থিতি একবার বোঝে, তারপর তার ভিত্তিতে প্রতিটি প্রকল্পকে র‍্যাঙ্ক করে — হাজার হাজারের মধ্যে কোনটি দেখতে হবে তা আপনার আগে থেকে জানা থাকার আশা না করে।',
  'landing.why3Title': 'আপনার ব্যবসাকে ঘিরে তৈরি, শুধু আপনার পরিচয় নয়',
