  'landing.whyHonestNote': 'স্কিমসেতু বর্তমানে {count}টি হাতে-যাচাই করা প্রকল্প কভার করে — সরকারের নিজস্ব পোর্টালে থাকা হাজার হাজারের একটি ক্ষুদ্র অংশ। এটি একটি ইচ্ছাকৃত সমঝোতা: এখানে প্রতিটি প্রকল্প বড় আকারে সংগ্রহ করার পরিবর্তে একটি প্রকৃত সরকারি উৎসের বিপরীতে আলাদাভাবে পরীক্ষা করা হয়েছে। আপাতত, ব্যাপ্তির চেয়ে গভীরতা।',
