  'landing.trust2Title': '{count} पडताळणी केलेल्या योजना',
  'landing.trust2Desc': 'केवळ भारत सरकारचे खरे कार्यक्रम — कोणताही बनावट डेटा नाही.',
  'landing.trust3Title': 'अधिकृत स्रोत जोडलेले',
  'landing.trust3Desc': 'प्रत्येक योजना ती परिभाषित करणाऱ्या सरकारी पानाशी जोडलेली आहे.',
  'landing.howItWorks': 'हे कसे काम करते',
  'landing.step1Title': '1. तुमची प्रोफाइल शेअर करा',
  'landing.step1Desc': 'प्रवर्ग, लिंग, राज्य, क्षेत्र, व्यवसायाचा टप्पा आणि पात्रतेचे काही साधे प्रश्न.',
  'landing.step2Title': '2. नियम-आधारित जुळणी',
  'landing.step2Desc': 'एक पारदर्शक, निश्चित गुणांकन प्रणाली तुमची प्रोफाइल प्रत्येक योजनेशी तपासते — कोणताही अंदाज नाही.',
  'landing.step3Title': '3. स्पष्टीकरणासह शिफारशी',
  'landing.step3Desc': 'तुमच्या सर्वोत्तम जुळण्या, प्रत्येक का जुळते (किंवा जुळत नाही) आणि अर्ज करण्यासाठीची अधिकृत पुढील पायरी पाहा.',
  'disclaimer.title': 'नियम-आधारित शिफारशी, अधिकृत निर्णय नाही.',
  'disclaimer.body': 'हा एक हॅकेथॉन प्रोटोटाइप आहे (SIH26092). अर्ज करण्यापूर्वी अंतिम पात्रता, लाभ, आवश्यक कागदपत्रे आणि अर्ज प्रक्रिया नेहमी संबंधित योजनेच्या अधिकृत सरकारी स्रोतावर पडताळून पाहा.',
  'methodology.title': 'या नियम-आधारित जुळण्या आहेत',
  'methodology.body': 'तुम्ही उत्तर दिलेल्या सात घटकांवरून काढलेल्या: प्रवर्ग, लिंग, राज्य, क्षेत्र, व्यवसायाचा टप्पा, प्रथमच उद्योजक स्थिती आणि उत्पन्न (दिले असल्यास). तुम्ही भरलेली इतर माहिती, जसे की व्यवसायाच्या गरजा, उलाढाल किंवा निधीची आवश्यकता, भविष्यातील मार्गदर्शन वैशिष्ट्यांसाठी जतन केली जाते, पण सध्या या गुणांवर परिणाम करत नाही.',
  'lowMatch.title': 'यापैकी अद्याप कोणतीही योजना ठामपणे जुळत नाही',
  'lowMatch.body': 'तुम्ही दिलेल्या माहितीनुसार, खालील योजना तुमच्या प्रोफाइलशी ठामपणे जुळत नाहीत. याचा अर्थ काहीच उपलब्ध नाही असे नाही — तुमचा प्रवर्ग, राज्य, क्षेत्र आणि व्यवसायाचा टप्पा पुन्हा तपासा, कारण एक लहान दुरुस्ती निकाल बदलू शकते. दरम्यान खाली दिलेल्या योजना वाचणे तरीही उपयुक्त ठरू शकते.',
  'lowMatch.cta': 'तुमची उत्तरे पुन्हा तपासा',
