  'checklist.detail.register-login': 'बहुतेक पोर्टलना खाते किंवा लॉगिन आवश्यक असते, जे बऱ्याचदा आधार किंवा व्यवसाय नोंदणीशी जोडलेले असते.',
  'checklist.detail.complete-application-fallback': 'या प्रोटोटाइपमध्ये योजना-विशिष्ट अर्ज प्रक्रिया अद्याप नोंद केलेली नाही — अधिकृत पोर्टल तुम्हाला त्याच्या स्वतःच्या प्रक्रियेतून मार्गदर्शन करेल.',
  'checklist.detail.upload-documents': 'पोर्टलला आवश्यक असलेली कागदपत्रे, त्याने स्वीकारलेल्या स्वरूपात आणि आकारात अपलोड करा.',
