  'landing.featuresTitle': 'योजना शोधण्यासाठी आणि अर्ज करण्यासाठी आवश्यक असलेले सर्व काही',
  'landing.feature1Title': 'भारांकित जुळणी गुणांकन',
  'landing.feature1Desc': 'एक पारदर्शक गुणांकन प्रणाली तुमची प्रोफाइल प्रवर्ग, लिंग, राज्य, क्षेत्र, व्यवसायाचा टप्पा आणि उत्पन्नाशी तपासते.',
  'landing.feature2Title': 'पात्रता स्थिती',
  'landing.feature2Desc': 'प्रत्येक योजना पात्र होण्याची शक्यता अधिक, पात्र होण्याची शक्यता, कमी जुळणी किंवा अपुरी माहिती अशी वर्गीकृत केली जाते.',
  'landing.feature3Title': 'जुळणारे आणि अपुरे निकष',
  'landing.feature3Desc': 'तुम्ही कोणते निकष पूर्ण करता, कोणत्यांना पडताळणी आवश्यक आहे आणि कोणते पूर्ण करत नाही हे नेमके पाहा — कोणतेही आश्चर्य नाही.',
  'landing.feature4Title': 'अनेक भारतीय भाषा',
  'landing.feature4Desc': 'मूल्यांकन आणि तुमचे निकाल {languages} भाषेत वापरा.',
  'landing.feature5Title': 'योजना नंतरसाठी जतन करा',
  'landing.feature5Desc': 'तुमच्या निकालांमधून किंवा ब्राउझरमधून कोणतीही योजना बुकमार्क करा आणि तुमच्या जतन केलेल्या यादीतून कधीही पुन्हा पाहा.',
  'landing.feature6Title': 'मूल्यांकनाशिवाय पाहा',
  'landing.feature6Desc': 'कोणत्याही वेळी संपूर्ण योजना यादी शोधा आणि फिल्टर करा — प्रोफाइलची गरज नाही.',
  'landing.whyEyebrow': 'स्कीमसेतू का',
  'landing.whyTitle': 'एका कामासाठी बनवलेले, प्रत्येक योजनेसाठी नाही',
  'landing.whySubtitle': 'एक केंद्रीय सरकारी पोर्टल आधीच हजारो योजना सूचीबद्ध करते. स्कीमसेतू त्याची जागा घेण्याचा प्रयत्न करत नाही — ते एक काम करते जे यादी करू शकत नाही: एखादी विशिष्ट योजना तुमच्यासाठी का लागू होते किंवा का नाही, हे नेमके दाखवणे.',
  'landing.why1Title': 'स्कोअर जे स्वतःच स्पष्ट करतात',
  'landing.why1Desc': 'प्रत्येक मॅच नेमके कोणते निकष पूर्ण झाले, चुकले, किंवा अयशस्वी झाले हे दाखवते — श्रेणी, लिंग, राज्य, क्षेत्र, व्यवसायाचा टप्पा, प्रथमच उद्योजक असण्याची स्थिती, आणि उत्पन्न — फक्त यादीतील एक नाव नाही.',
  'landing.why2Title': 'एक मार्गदर्शित मार्ग, शोध पेटी नाही',
  'landing.why2Desc': 'एक छोटे मूल्यांकन तुमची परिस्थिती एकदा समजून घेते, मग त्याआधारे प्रत्येक योजनेला क्रमवारी लावते — हजारोंपैकी कोणती पाहायची हे तुम्हाला आधीच माहीत असावे अशी अपेक्षा न ठेवता.',
  'landing.why3Title': 'तुमच्या व्यवसायाभोवती बनवलेले, फक्त तुमच्या ओळखीवर आधारित नाही',
  'landing.why3Desc': 'मॅच तुमचे व्यवसाय क्षेत्र, टप्पा, आणि प्रथमच उद्योजक असण्याची स्थिती देखील मोजतात — फक्त लोकसंख्याशास्त्रीय पात्रता नाही — जेणेकरून निकाल तुमचा उद्यम खरोखर कुठे आहे हे दाखवतील.',
  'landing.why4Title': 'इंटरनेटशिवायही काम करते',
  'landing.why4Desc': 'अ‍ॅप म्हणून इन्स्टॉल करता येते आणि ऑफलाइन वापरासाठी साठवले जाते, जेणेकरून जतन केलेले मूल्यांकन आणि पाहिलेल्या योजना सिग्नलशिवायही उपलब्ध राहतील.',
  'landing.why5Title': '१२ भारतीय भाषांमध्ये, पूर्णपणे',
  'landing.why5Desc': 'संपूर्ण मूल्यांकन, निकाल, आणि स्पष्टीकरणे भाषांतरित आहेत — फक्त पानाचे शीर्षक आणि बटणे नाहीत.',
  'landing.whyHonestNote': 'स्कीमसेतू सध्या {count} हाताने पडताळलेल्या योजना कव्हर करते — सरकारच्या स्वतःच्या पोर्टलवरील हजारोंपैकी एक छोटा भाग. हा एक जाणीवपूर्वक तडजोड आहे: येथील प्रत्येक योजना मोठ्या प्रमाणावर गोळा करण्याऐवजी खऱ्या अधिकृत स्रोताविरुद्ध वैयक्तिकरित्या तपासली आहे. सध्या, व्याप्तीपेक्षा खोली महत्त्वाची.',
  'landing.ctaBandTitle': 'तुमच्या योजना शोधण्यासाठी तयार आहात का?',
  'landing.ctaBandSubtitle': 'एक छोटे मूल्यांकन पूर्ण करा आणि काही मिनिटांत वैयक्तिकृत, स्पष्टीकरणासह योजना शिफारशी मिळवा.',
  'landing.ctaBandButton': 'मूल्यांकन सुरू करा',
  'footer.blurb': 'एक नियम-आधारित प्लॅटफॉर्म जे उपेक्षित उद्योजकांना त्यांच्या व्यवसाय प्रोफाइल, पात्रता आणि गरजांनुसार संबंधित सरकारी योजनांशी जुळवते.',
  'footer.builtFor': 'स्मार्ट इंडिया हॅकेथॉनसाठी तयार केलेले — SIH26092. हा प्रात्यक्षिकासाठीचा एक प्रोटोटाइप आहे.',
