  'emi.title': 'EMI కాలిక్యులేటర్',
  'emi.subtitle': 'ఏదైనా లోన్ మొత్తం, వడ్డీ రేటు మరియు కాలవ్యవధికి నెలవారీ వాయిదాను అంచనా వేయండి.',
  'emi.principalLabel': 'లోన్ మొత్తం (₹)',
