  'emi.legendPrincipal': 'అసలు మొత్తం',
  'emi.legendInterest': 'వడ్డీ',
  'emi.invalidInputs': 'మీ EMI చూడటానికి చెల్లుబాటు అయ్యే లోన్ మొత్తం మరియు కాలవ్యవధిని నమోదు చేయండి.',
  'emi.disclaimer':
    'ఇది సాధారణ అంచనా మాత్రమే. వాస్తవ వడ్డీ రేట్లు మరియు నిబంధనలు రుణదాత బ్యాంక్ లేదా NBFC నిర్ణయిస్తుంది మరియు పథకం, దరఖాస్తుదారు, శాఖను బట్టి మారుతుంది — ఎల్లప్పుడూ రుణదాతతో నిర్ధారించుకోండి.',
  'emi.pageTitle': 'EMI కాలిక్యులేటర్',
  'emi.pageSubtitle': 'ఇది ఏ నిర్దిష్ట పథకానికి సంబంధించినది కాదు — నెలవారీ వాయిదాను అంచనా వేయడానికి మీ స్వంత సంఖ్యలను నమోదు చేయండి.',
  'offline.title': 'మీరు ఆఫ్‌లైన్‌లో ఉన్నారు',
  'offline.body':
    'ఈ పేజీ ఇంకా సేవ్ కాలేదు. దీన్ని లోడ్ చేయడానికి మళ్లీ కనెక్ట్ అవ్వండి, లేదా మీరు ఇంతకుముందు తెరిచిన ఏదైనా పేజీని చూడండి — అది ఆఫ్‌లైన్‌లో కూడా పనిచేస్తూనే ఉంటుంది.',
  'pwa.install': 'యాప్‌ను ఇన్‌స్టాల్ చేయండి',
  'pwa.installed': 'ఇన్‌స్టాల్ చేయబడింది',
  'error.title': 'ఏదో తప్పు జరిగింది',
  'error.body':
    'ఈ పేజీలో ఊహించని లోపం ఏర్పడింది. మీరు మళ్ళీ ప్రయత్నించవచ్చు, లేదా హోమ్‌పేజీకి తిరిగి వెళ్లవచ్చు — యాప్‌లోని మిగతా భాగానికి ఎలాంటి ప్రభావం లేదు.',
  'error.startOver': 'మళ్ళీ మొదలుపెట్టండి',
