  'landing.heroSubtitle': 'பெண்கள், SC/ST, OBC, கிராமப்புற, குறைந்த வருமானம் கொண்ட மற்றும் முதன்முறை தொழில்முனைவோருக்காக வடிவமைக்கப்பட்டது. ஒரு சிறு சுயவிவரக் கேள்வித்தாளுக்குப் பதிலளியுங்கள், வெளிப்படையான விதி அடிப்படையிலான பொருத்தும் இயந்திரத்தால் ஆதரிக்கப்படும் தரவரிசைப்படுத்தப்பட்ட, விளக்கமளிக்கக்கூடிய திட்டப் பரிந்துரைகளைப் பெறுங்கள் — உங்களுக்காக யூகிக்கும் சாட்பாட் அல்ல.',
