  'landing.schemeCount': '{count} சரிபார்க்கப்பட்ட அரசுத் திட்டங்கள் தற்போதைய தரவுத்தொகுப்பில் உள்ளன, ஒவ்வொன்றிற்கும் அதிகாரப்பூர்வ மூல இணைப்புடன்.',
  'landing.browseAll': 'முழு பட்டியலையும் பார்வையிடுங்கள் →',
  'landing.trust1Title': 'விதி அடிப்படையிலானது, கருப்புப் பெட்டி அல்ல',
  'landing.trust1Desc': 'ஒவ்வொரு மதிப்பெண்ணும் ஆவணப்படுத்தப்பட்ட தகுதி விதியிலிருந்து கண்டறியப்படுகிறது.',
