  'landing.trust2Desc': 'உண்மையான இந்திய அரசு திட்டங்கள் மட்டுமே — கற்பனையான தரவு இல்லை.',
  'landing.trust3Title': 'அதிகாரப்பூர்வ மூலங்கள் இணைக்கப்பட்டுள்ளன',
  'landing.trust3Desc': 'ஒவ்வொரு திட்டமும் அதை வரையறுக்கும் அரசுப் பக்கத்துடன் இணைக்கப்பட்டுள்ளது.',
  'landing.howItWorks': 'இது எவ்வாறு செயல்படுகிறது',
  'landing.step1Title': '1. உங்கள் சுயவிவரத்தைப் பகிருங்கள்',
  'landing.step1Desc': 'பிரிவு, பாலினம், மாநிலம், துறை, தொழில் நிலை, மற்றும் சில விரைவான தகுதிக் கேள்விகள்.',
  'landing.step2Title': '2. விதி அடிப்படையிலான பொருத்தம்',
  'landing.step2Desc': 'ஒரு வெளிப்படையான, உறுதியான மதிப்பீட்டு இயந்திரம் உங்கள் சுயவிவரத்தை ஒவ்வொரு திட்டத்துடனும் ஒப்பிட்டுச் சரிபார்க்கிறது — யூகிப்பு இல்லை.',
  'landing.step3Title': '3. விளக்கமளிக்கக்கூடிய பரிந்துரைகள்',
  'landing.step3Desc': 'உங்கள் சிறந்த பொருத்தங்களைக் காணுங்கள், ஒவ்வொன்றும் ஏன் பொருந்துகிறது (அல்லது இல்லை) என்பதையும், விண்ணப்பிக்க அதிகாரப்பூர்வ அடுத்த கட்டத்தையும் அறியுங்கள்.',
  'disclaimer.title': 'விதி அடிப்படையிலான பரிந்துரைகள், ஒரு அதிகாரப்பூர்வ முடிவு அல்ல.',
  'disclaimer.body': 'இது ஒரு ஹேக்கத்தான் முன்மாதிரி (SIH26092). விண்ணப்பிக்கும் முன் இறுதி தகுதி, பலன்கள், தேவையான ஆவணங்கள் மற்றும் விண்ணப்ப நடைமுறைகளை திட்டத்தின் அதிகாரப்பூர்வ அரசு மூலத்தில் எப்போதும் சரிபார்க்கவும்.',
  'methodology.title': 'இவை விதி அடிப்படையிலான பொருத்தங்கள்',
  'methodology.body': 'நீங்கள் பதிலளித்த ஏழு காரணிகளிலிருந்து கணக்கிடப்படுகிறது: பிரிவு, பாலினம், மாநிலம், துறை, தொழில் நிலை, முதன்முறை தொழில்முனைவோர் நிலை, மற்றும் வருமானம் (கொடுக்கப்பட்டிருந்தால்). நீங்கள் உள்ளிட்ட மற்ற விவரங்கள், அதாவது தொழில் தேவைகள், வருவாய், அல்லது நிதி தேவை போன்றவை, எதிர்கால வழிகாட்டல் அம்சங்களுக்காகச் சேமிக்கப்படுகின்றன, ஆனால் இந்த மதிப்பெண்ணை இன்னும் பாதிக்காது.',
  'lowMatch.title': 'இவற்றில் எதுவும் இன்னும் வலுவான பொருத்தம் இல்லை',
  'lowMatch.body': 'நீங்கள் பகிர்ந்த தகவலின் அடிப்படையில், கீழே உள்ள திட்டங்கள் உங்கள் சுயவிவரத்துடன் வலுவாகப் பொருந்தவில்லை. அதற்காக எதுவும் கிடைக்காது என்று அர்த்தமல்ல — உங்கள் பிரிவு, மாநிலம், துறை, மற்றும் தொழில் நிலையை மீண்டும் சரிபார்க்கவும், ஏனெனில் ஒரு சிறிய திருத்தம் முடிவை மாற்றக்கூடும். இதற்கிடையில் கீழே பட்டியலிடப்பட்டுள்ள திட்டங்களைப் படிப்பது இன்னும் பயனுள்ளதாக இருக்கும்.',
