  'assessment.privacyNote': 'தனியுரிமை: உங்கள் பதில்கள் இந்தச் சாதனத்திலேயே சேமிக்கப்படும் (இந்த உலாவியுடன் மட்டும் இணைக்கப்பட்ட தனிப்பட்ட காப்புப்பிரதியும் இருக்கலாம்), இதனால் நீங்கள் பின்னர் தொடரலாம். பொருத்தமான திட்டங்களைக் கண்டறிய மட்டுமே இவை பயன்படுத்தப்படுகின்றன. “{startOver}” இவற்றை நீக்கும்.',
