  'assessment.step.business.title': 'தொழில் தகவல்',
  'assessment.step.business.description': 'துறை, நிலை, மற்றும் முதன்முறை நிலை திட்டங்களை உங்கள் வகை தொழிலுக்கு ஏற்பக் குறுக்குகின்றன.',
  'assessment.step.financial.title': 'நிதி தகவல்',
  'assessment.step.financial.description': 'வருமானம் (விருப்பத் தேர்வு) வருமான வரம்புள்ள திட்டங்களைப் பொருத்த உதவும்; மற்றவை உங்கள் தேவைகளைப் புரிந்துகொள்ள உதவுகின்றன.',
