  'disclaimer.body': 'આ એક હેકાથોન પ્રોટોટાઇપ છે (SIH26092). અરજી કરતા પહેલાં હંમેશા યોજનાના સત્તાવાર સરકારી સ્રોત પર અંતિમ પાત્રતા, લાભો, જરૂરી દસ્તાવેજો અને અરજી પ્રક્રિયાની ચકાસણી કરો.',
