  'checklist.detail.register-login': 'મોટાભાગના પોર્ટલને ખાતું અથવા લોગ ઇનની જરૂર હોય છે, જે ઘણી વાર આધાર અથવા વ્યવસાય નોંધણી સાથે જોડાયેલું હોય છે.',
  'checklist.detail.complete-application-fallback': 'આ પ્રોટોટાઇપમાં યોજના-વિશિષ્ટ અરજી પગલાં હજુ સૂચિબદ્ધ નથી — સત્તાવાર પોર્ટલ તમને તેની પોતાની પ્રક્રિયામાંથી પસાર કરશે.',
