  'checklist.stepsChecked': '{total} ರಲ್ಲಿ {done} ಹಂತಗಳನ್ನು ಗುರುತಿಸಲಾಗಿದೆ',
  'checklist.officialPortal': 'ಅಧಿಕೃತ ಅರ್ಜಿ ಪೋರ್ಟಲ್',
  'checklist.next': 'ಮುಂದೆ: {step}',
  'checklist.allDone': 'ಈ ಸೆಷನ್‌ಗೆ ಎಲ್ಲಾ ಹಂತಗಳನ್ನು ಗುರುತಿಸಲಾಗಿದೆ — ಸಲ್ಲಿಸುವ ಮೊದಲು ಅಧಿಕೃತ ಮೂಲದಲ್ಲಿ ಎಲ್ಲವನ್ನೂ ಮತ್ತೊಮ್ಮೆ ಪರಿಶೀಲಿಸಿ.',
  'checklist.footerNote': 'ಏನನ್ನಾದರೂ ಸಲ್ಲಿಸುವ ಮೊದಲು ಮೇಲಿನ ಅಧಿಕೃತ ಮೂಲದಲ್ಲಿ ಅಂತಿಮ ಅರ್ಹತೆ, ದಾಖಲೆಗಳು ಮತ್ತು ಅರ್ಜಿ ಸಲ್ಲಿಕೆ ಹಂತಗಳನ್ನು ಯಾವಾಗಲೂ ಪರಿಶೀಲಿಸಿ.',
  'checklist.findCscHelp': 'ವೈಯಕ್ತಿಕವಾಗಿ ಸಹಾಯ ಬೇಕೇ? ನಿಮ್ಮ ಹತ್ತಿರದ ಕಾಮನ್ ಸರ್ವಿಸ್ ಸೆಂಟರ್ (CSC) ಹುಡುಕಿ',
  'checklist.completed': 'ಪೂರ್ಣಗೊಂಡಿದೆ',
