  'checklist.step.visit-portal': 'ಅಧಿಕೃತ ಅರ್ಜಿ ಪೋರ್ಟಲ್‌ಗೆ ಭೇಟಿ ನೀಡಿ',
  'checklist.step.register-login': 'ನೋಂದಣಿ / ಲಾಗಿನ್ ಮಾಡಿ',
  'checklist.step.complete-application': 'ಅರ್ಜಿಯನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ',
  'checklist.step.upload-documents': 'ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ',
  'checklist.step.submit-track': 'ಸಲ್ಲಿಸಿ ಮತ್ತು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ',
  'checklist.detail.check-eligibility': 'ಅಧಿಕೃತ ಮೂಲದಲ್ಲಿ ನೀವು ಈ ಯೋಜನೆಯ ಅರ್ಹತಾ ನಿಯಮಗಳನ್ನು ಪೂರೈಸುತ್ತೀರಾ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ — ಈ ಪುಟದಲ್ಲಿ ತೋರಿಸಿರುವ ಹೊಂದಾಣಿಕೆ ಒಂದು ಸರಳೀಕೃತ ಪ್ರೋಟೋಟೈಪ್ ಅಂದಾಜು, ಅಂತಿಮ ನಿರ್ಧಾರವಲ್ಲ.',
  'checklist.detail.prepare-documents-fallback': 'ಈ ಪ್ರೋಟೋಟೈಪ್‌ನಲ್ಲಿ ಯೋಜನೆ-ನಿರ್ದಿಷ್ಟ ದಾಖಲೆಗಳನ್ನು ಇನ್ನೂ ಪಟ್ಟಿ ಮಾಡಿಲ್ಲ — ಪ್ರಸ್ತುತ ಪಟ್ಟಿಗಾಗಿ ಕೆಳಗಿನ ಅಧಿಕೃತ ಮೂಲವನ್ನು ಪರಿಶೀಲಿಸಿ.',
  'checklist.detail.visit-portal-fallback': 'ಈ ನಮೂದಿಗೆ ಯಾವುದೇ ಅಧಿಕೃತ ಮೂಲ ಲಿಂಕ್ ದಾಖಲಾಗಿಲ್ಲ.',
  'checklist.detail.register-login': 'ಹೆಚ್ಚಿನ ಪೋರ್ಟಲ್‌ಗಳಿಗೆ ಖಾತೆ ಅಥವಾ ಲಾಗಿನ್ ಬೇಕಾಗುತ್ತದೆ, ಇದು ಸಾಮಾನ್ಯವಾಗಿ ಆಧಾರ್ ಅಥವಾ ಉದ್ಯಮ ನೋಂದಣಿಗೆ ಜೋಡಣೆಯಾಗಿರುತ್ತದೆ.',
  'checklist.detail.complete-application-fallback': 'ಈ ಪ್ರೋಟೋಟೈಪ್‌ನಲ್ಲಿ ಯೋಜನೆ-ನಿರ್ದಿಷ್ಟ ಅರ್ಜಿ ಸಲ್ಲಿಕೆ ಹಂತಗಳನ್ನು ಇನ್ನೂ ಪಟ್ಟಿ ಮಾಡಿಲ್ಲ — ಅಧಿಕೃತ ಪೋರ್ಟಲ್ ನಿಮಗೆ ಅದರ ಸ್ವಂತ ಪ್ರಕ್ರಿಯೆಯ ಮೂಲಕ ಮಾರ್ಗದರ್ಶನ ನೀಡುತ್ತದೆ.',
  'checklist.detail.upload-documents': 'ಪೋರ್ಟಲ್ ಕೇಳುವ ದಾಖಲೆಗಳನ್ನು, ಅದು ಸ್ವೀಕರಿಸುವ ಸ್ವರೂಪ ಮತ್ತು ಗಾತ್ರದಲ್ಲಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ.',
  'checklist.detail.submit-track': 'ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಿ ಮತ್ತು ಪೋರ್ಟಲ್ ನೀಡುವ ಯಾವುದೇ ಉಲ್ಲೇಖ ಅಥವಾ ಟ್ರ್ಯಾಕಿಂಗ್ ಸಂಖ್ಯೆಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳಿ.',
