  'landing.trust4Desc': 'ಸಂಕೀರ್ಣ ಸರ್ಕಾರಿ ಪರಿಭಾಷೆ ಇಲ್ಲ — ಪ್ರತಿ ಹೊಂದಾಣಿಕೆಯೂ ಏಕೆ ಎಂಬುದರ ಸರಳ ವಿವರಣೆಯೊಂದಿಗೆ ಬರುತ್ತದೆ.',
