  'nav.unsavedGuard': 'ਤੁਹਾਡੇ ਕੋਲ ਮੁਲਾਂਕਣ ਦੇ ਅਣਸੰਭਾਲੇ ਜਵਾਬ ਹਨ। ਇਹ ਪੰਨਾ ਛੱਡੋ ਅਤੇ ਆਪਣੀ ਤਰੱਕੀ ਗੁਆਓ?',

  'landing.eyebrow': 'SIH26092 · ਪ੍ਰੋਟੋਟਾਈਪ',
  'landing.readInLabel': 'ਇਸ ਵਿੱਚ ਪੜ੍ਹੋ:',
  'landing.heroTitle': 'ਪਤਾ ਲਗਾਓ ਕਿ ਤੁਸੀਂ ਅਸਲ ਵਿੱਚ ਕਿਹੜੀਆਂ ਸਰਕਾਰੀ ਸਕੀਮਾਂ ਲਈ ਯੋਗ ਹੋ',
  'landing.heroSubtitle':
    'ਔਰਤਾਂ, SC/ST, OBC, ਪੇਂਡੂ, ਘੱਟ ਆਮਦਨ ਵਾਲੇ ਅਤੇ ਪਹਿਲੀ ਵਾਰ ਉੱਦਮ ਸ਼ੁਰੂ ਕਰਨ ਵਾਲਿਆਂ ਲਈ ਬਣਾਇਆ ਗਿਆ। ਇੱਕ ਛੋਟੀ ਪ੍ਰੋਫਾਈਲ ਭਰੋ, ਅਤੇ ਇੱਕ ਪਾਰਦਰਸ਼ੀ, ਨਿਯਮ-ਆਧਾਰਿਤ ਮੈਚਿੰਗ ਇੰਜਣ ਤੋਂ ਦਰਜਾਬੰਦੀ ਵਾਲੀਆਂ, ਸਪਸ਼ਟ ਸਕੀਮ ਸਿਫ਼ਾਰਸ਼ਾਂ ਪ੍ਰਾਪਤ ਕਰੋ — ਕਿਸੇ ਅੰਦਾਜ਼ਾ ਲਗਾਉਣ ਵਾਲੇ ਚੈਟਬੋਟ ਤੋਂ ਨਹੀਂ।',
  'landing.ctaStart': 'ਮੁਲਾਂਕਣ ਸ਼ੁਰੂ ਕਰੋ',
  'landing.ctaDemo': 'ਇੱਕ ਲਾਈਵ ਡੈਮੋ ਪ੍ਰੋਫਾਈਲ ਦੇਖੋ',
  'landing.schemeCount': 'ਮੌਜੂਦਾ ਡੇਟਾਸੈੱਟ ਵਿੱਚ {count} ਪ੍ਰਮਾਣਿਤ ਸਰਕਾਰੀ ਸਕੀਮਾਂ, ਹਰੇਕ ਦੇ ਨਾਲ ਇੱਕ ਅਧਿਕਾਰਤ ਸਰੋਤ ਲਿੰਕ।',
  'landing.browseAll': 'ਪੂਰੀ ਸੂਚੀ ਦੇਖੋ →',
  'landing.trust1Title': 'ਨਿਯਮ-ਆਧਾਰਿਤ, ਬਲੈਕ ਬਾਕਸ ਨਹੀਂ',
  'landing.trust1Desc': 'ਹਰ ਸਕੋਰ ਇੱਕ ਦਸਤਾਵੇਜ਼ੀ ਯੋਗਤਾ ਨਿਯਮ ਤੋਂ ਆਉਂਦਾ ਹੈ।',
  'landing.trust2Title': '{count} ਪ੍ਰਮਾਣਿਤ ਸਕੀਮਾਂ',
  'landing.trust2Desc': 'ਸਿਰਫ਼ ਅਸਲੀ ਭਾਰਤ ਸਰਕਾਰ ਦੇ ਪ੍ਰੋਗਰਾਮ — ਕੋਈ ਘੜਿਆ ਹੋਇਆ ਡੇਟਾ ਨਹੀਂ।',
  'landing.trust3Title': 'ਅਧਿਕਾਰਤ ਸਰੋਤ ਜੁੜੇ ਹੋਏ',
  'landing.trust3Desc': 'ਹਰ ਸਕੀਮ ਉਸ ਸਰਕਾਰੀ ਪੰਨੇ ਨਾਲ ਜੁੜੀ ਹੈ ਜੋ ਇਸਨੂੰ ਪਰਿਭਾਸ਼ਿਤ ਕਰਦਾ ਹੈ।',
  'landing.howItWorks': 'ਇਹ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ',
  'landing.step1Title': '1. ਆਪਣੀ ਪ੍ਰੋਫਾਈਲ ਸਾਂਝੀ ਕਰੋ',
  'landing.step1Desc': 'ਸ਼੍ਰੇਣੀ, ਲਿੰਗ, ਰਾਜ, ਖੇਤਰ, ਕਾਰੋਬਾਰੀ ਪੜਾਅ, ਅਤੇ ਕੁਝ ਤੇਜ਼ ਯੋਗਤਾ ਸਵਾਲ।',
  'landing.step2Title': '2. ਨਿਯਮ-ਆਧਾਰਿਤ ਮੈਚਿੰਗ',
  'landing.step2Desc': 'ਇੱਕ ਪਾਰਦਰਸ਼ੀ, ਨਿਸ਼ਚਿਤ ਸਕੋਰਿੰਗ ਇੰਜਣ ਤੁਹਾਡੀ ਪ੍ਰੋਫਾਈਲ ਨੂੰ ਹਰ ਸਕੀਮ ਦੇ ਵਿਰੁੱਧ ਜਾਂਚਦਾ ਹੈ — ਕੋਈ ਅੰਦਾਜ਼ਾ ਨਹੀਂ।',
  'landing.step3Title': '3. ਸਪਸ਼ਟ ਸਿਫ਼ਾਰਸ਼ਾਂ',
  'landing.step3Desc': 'ਆਪਣੇ ਸਿਖਰਲੇ ਮੈਚ ਦੇਖੋ, ਹਰ ਇੱਕ ਕਿਉਂ ਢੁਕਵਾਂ ਹੈ (ਜਾਂ ਨਹੀਂ), ਅਤੇ ਅਰਜ਼ੀ ਦੇਣ ਲਈ ਅਗਲਾ ਅਧਿਕਾਰਤ ਕਦਮ।',

  'disclaimer.title': 'ਨਿਯਮ-ਆਧਾਰਿਤ ਸਿਫ਼ਾਰਸ਼ਾਂ, ਕੋਈ ਅਧਿਕਾਰਤ ਫੈਸਲਾ ਨਹੀਂ।',
  'disclaimer.body':
    "ਇਹ ਇੱਕ ਹੈਕਾਥਾਨ ਪ੍ਰੋਟੋਟਾਈਪ (SIH26092) ਹੈ। ਅਰਜ਼ੀ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਹਮੇਸ਼ਾ ਅੰਤਿਮ ਯੋਗਤਾ, ਲਾਭ, ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼ ਅਤੇ ਅਰਜ਼ੀ ਦੇ ਕਦਮ ਸਕੀਮ ਦੇ ਅਧਿਕਾਰਤ ਸਰਕਾਰੀ ਸਰੋਤ 'ਤੇ ਪੁਸ਼ਟੀ ਕਰੋ।",
  'methodology.title': 'ਇਹ ਨਿਯਮ-ਆਧਾਰਿਤ ਮੈਚ ਹਨ',
  'methodology.body':
    'ਤੁਹਾਡੇ ਦੁਆਰਾ ਦਿੱਤੇ ਸੱਤ ਕਾਰਕਾਂ ਤੋਂ ਗਿਣੇ ਗਏ: ਸ਼੍ਰੇਣੀ, ਲਿੰਗ, ਰਾਜ, ਖੇਤਰ, ਕਾਰੋਬਾਰੀ ਪੜਾਅ, ਪਹਿਲੀ ਵਾਰ ਦੀ ਸਥਿਤੀ, ਅਤੇ ਆਮਦਨ (ਜੇ ਦਿੱਤੀ ਗਈ ਹੋਵੇ)। ਤੁਹਾਡੇ ਦੁਆਰਾ ਦਰਜ ਹੋਰ ਵੇਰਵੇ, ਜਿਵੇਂ ਕਾਰੋਬਾਰੀ ਲੋੜਾਂ, ਟਰਨਓਵਰ, ਜਾਂ ਫੰਡਿੰਗ ਲੋੜ, ਭਵਿੱਖ ਦੀਆਂ ਮਾਰਗਦਰਸ਼ਨ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਲਈ ਸੰਭਾਲੇ ਗਏ ਹਨ ਪਰ ਹਾਲੇ ਇਸ ਸਕੋਰ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਨਹੀਂ ਕਰਦੇ।',
  'lowMatch.title': 'ਹਾਲੇ ਤੱਕ ਇਹਨਾਂ ਵਿੱਚੋਂ ਕੋਈ ਵੀ ਮਜ਼ਬੂਤ ਮੈਚ ਨਹੀਂ ਹੈ',
  'lowMatch.body':
    'ਤੁਹਾਡੇ ਦੁਆਰਾ ਸਾਂਝੀ ਕੀਤੀ ਜਾਣਕਾਰੀ ਦੇ ਆਧਾਰ ਤੇ, ਹੇਠਾਂ ਦਿੱਤੀਆਂ ਸਕੀਮਾਂ ਤੁਹਾਡੀ ਪ੍ਰੋਫਾਈਲ ਨਾਲ ਮਜ਼ਬੂਤੀ ਨਾਲ ਮੇਲ ਨਹੀਂ ਖਾਂਦੀਆਂ। ਇਸਦਾ ਮਤਲਬ ਇਹ ਨਹੀਂ ਕਿ ਕੁਝ ਵੀ ਉਪਲਬਧ ਨਹੀਂ — ਆਪਣੀ ਸ਼੍ਰੇਣੀ, ਰਾਜ, ਖੇਤਰ ਅਤੇ ਕਾਰੋਬਾਰੀ ਪੜਾਅ ਦੁਬਾਰਾ ਜਾਂਚੋ, ਕਿਉਂਕਿ ਇੱਕ ਛੋਟੀ ਸੋਧ ਨਤੀਜਾ ਬਦਲ ਸਕਦੀ ਹੈ। ਹੇਠਾਂ ਸੂਚੀਬੱਧ ਸਕੀਮਾਂ ਫਿਰ ਵੀ ਪੜ੍ਹਨ ਯੋਗ ਹਨ।',
  'lowMatch.cta': 'ਆਪਣੇ ਜਵਾਬ ਦੇਖੋ',

