  'nav.toolsMenu': 'ਸੰਦ',
  'nav.moreMenu': 'ਹੋਰ',
  'institutions.title': 'ਇਹ ਸਕੀਮਾਂ ਕੌਣ ਚਲਾਉਂਦਾ ਹੈ',
  'institutions.subtitle':
    'ਇਸ ਡੇਟਾਸੈੱਟ ਵਿੱਚ ਹਰ ਸਕੀਮ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰਨ ਵਾਲੀਆਂ ਅਸਲ ਸਰਕਾਰੀ ਸੰਸਥਾਵਾਂ ਅਤੇ ਨਿਗਮਾਂ ਨੂੰ ਦੇਖੋ — ਇਹ ਕੋਈ ਬ੍ਰਾਂਚ ਲੋਕੇਟਰ ਨਹੀਂ ਹੈ, ਸਿਰਫ਼ ਇਹ ਇਮਾਨਦਾਰ ਜਾਣਕਾਰੀ ਹੈ ਕਿ ਕਿਸ ਕੋਲ ਜਾਣਾ ਹੈ।',
  'institutions.searchPlaceholder': 'ਸੰਸਥਾਵਾਂ ਜਾਂ ਸਕੀਮਾਂ ਖੋਜੋ…',
  'institutions.showingCount': '{total} ਵਿੱਚੋਂ {shown} ਸੰਸਥਾਵਾਂ ਦਿਖਾਈਆਂ ਜਾ ਰਹੀਆਂ ਹਨ',
  'schemeDetails.quickRefAdministeredBy': 'ਦੁਆਰਾ ਪ੍ਰਬੰਧਿਤ',
  'schemeDetails.quickRefEmi': 'ਆਪਣੀ ਲੋਨ EMI ਦਾ ਅਨੁਮਾਨ ਲਗਾਓ',
  'emi.title': 'EMI ਕੈਲਕੁਲੇਟਰ',
  'emi.subtitle': 'ਕਿਸੇ ਵੀ ਲੋਨ ਰਕਮ, ਵਿਆਜ ਦਰ ਅਤੇ ਮਿਆਦ ਲਈ ਮਾਸਿਕ ਕਿਸ਼ਤ ਦਾ ਅਨੁਮਾਨ ਲਗਾਓ।',
  'emi.principalLabel': 'ਲੋਨ ਰਕਮ (₹)',
