  'emi.totalInterest': 'ਕੁੱਲ ਵਿਆਜ',
  'emi.totalPayment': 'ਕੁੱਲ ਭੁਗਤਾਨ',
  'emi.breakdownAria': 'ਮੂਲ ਧਨ ਕੁੱਲ ਭੁਗਤਾਨ ਦਾ {principalPct}% ਹੈ ਅਤੇ ਵਿਆਜ {interestPct}% ਹੈ',
  'emi.legendPrincipal': 'ਮੂਲ ਧਨ',
