  'disclaimer.title': 'ନିୟମ-ଆଧାରିତ ସୁପାରିଶ, କୌଣସି ସରକାରୀ ନିଷ୍ପତ୍ତି ନୁହେଁ।',
  'disclaimer.body':
    'ଏହା ଏକ ହ୍ୟାକାଥନ୍ ପ୍ରୋଟୋଟାଇପ୍ (SIH26092)। ଆବେଦନ କରିବା ପୂର୍ବରୁ ସର୍ବଦା ଅନ୍ତିମ ଯୋଗ୍ୟତା, ଲାଭ, ଆବଶ୍ୟକ ଦଲିଲ ଏବଂ ଆବେଦନ ପଦକ୍ଷେପଗୁଡ଼ିକ ଯୋଜନାର ସରକାରୀ ଉତ୍ସରେ ଯାଞ୍ଚ କରନ୍ତୁ।',
  'methodology.title': 'ଏଗୁଡ଼ିକ ନିୟମ-ଆଧାରିତ ମେଳନ',
  'methodology.body':
    'ଆପଣ ଦେଇଥିବା ସାତଟି କାରକରୁ ଗଣନା କରାଯାଇଛି: ବର୍ଗ, ଲିଙ୍ଗ, ରାଜ୍ୟ, କ୍ଷେତ୍ର, ବ୍ୟବସାୟ ପର୍ଯ୍ୟାୟ, ପ୍ରଥମ ଥର ସ୍ଥିତି, ଏବଂ ଆୟ (ଯଦି ଦିଆଯାଇଛି)। ଆପଣ ଦେଇଥିବା ଅନ୍ୟ ବିବରଣୀ, ଯେପରି ବ୍ୟବସାୟ ଆବଶ୍ୟକତା, ଟର୍ନଓଭର, କିମ୍ବା ପାଣ୍ଠି ଆବଶ୍ୟକତା, ଭବିଷ୍ୟତର ମାର୍ଗଦର୍ଶନ ବିଶେଷତା ପାଇଁ ସାଇତି ରଖାଯାଇଛି କିନ୍ତୁ ବର୍ତ୍ତମାନ ଏହି ସ୍କୋରକୁ ପ୍ରଭାବିତ କରେ ନାହିଁ।',
  'lowMatch.title': 'ଏହା ମଧ୍ୟରୁ ଏପର୍ଯ୍ୟନ୍ତ କୌଣସିଟି ଏକ ଦୃଢ଼ ମେଳନ ନୁହେଁ',
  'lowMatch.body':
    'ଆପଣ ସେୟାର କରିଥିବା ସୂଚନା ଆଧାରରେ, ନିମ୍ନରେ ଥିବା ଯୋଜନାଗୁଡ଼ିକ ଆପଣଙ୍କର ପ୍ରୋଫାଇଲ୍ ସହିତ ଦୃଢ଼ ଭାବେ ମେଳ ଖାଉ ନାହାଁନ୍ତି। ଏହାର ଅର୍ଥ ନୁହେଁ ଯେ କିଛି ଉପଲବ୍ଧ ନାହିଁ — ଆପଣଙ୍କର ବର୍ଗ, ରାଜ୍ୟ, କ୍ଷେତ୍ର ଏବଂ ବ୍ୟବସାୟ ପର୍ଯ୍ୟାୟ ପୁନଃ ଯାଞ୍ଚ କରନ୍ତୁ, କାରଣ ଏକ ଛୋଟ ସଂଶୋଧନ ଫଳାଫଳ ବଦଳାଇପାରେ। ନିମ୍ନରେ ତାଲିକାଭୁକ୍ତ ଯୋଜନାଗୁଡ଼ିକ ତଥାପି ପଢ଼ିବା ଯୋଗ୍ୟ।',
  'lowMatch.cta': 'ଆପଣଙ୍କର ଉତ୍ତର ସମୀକ୍ଷା କରନ୍ତୁ',

