  'landing.feature6Title': 'ମୂଲ୍ୟାୟନ ବିନା ବ୍ରାଉଜ୍ କରନ୍ତୁ',
  'landing.feature6Desc': 'ଯେକୌଣସି ସମୟରେ ସମ୍ପୂର୍ଣ୍ଣ ଯୋଜନା ତାଲିକା ଖୋଜନ୍ତୁ ଏବଂ ଫିଲ୍ଟର କରନ୍ତୁ — କୌଣସି ପ୍ରୋଫାଇଲ୍ ଆବଶ୍ୟକ ନାହିଁ।',
  'landing.whyEyebrow': 'କାହିଁକି ସ୍କିମସେତୁ',
  'landing.whyTitle': 'ଗୋଟିଏ କାମ ପାଇଁ ତିଆରି, ପ୍ରତ୍ୟେକ ଯୋଜନା ପାଇଁ ନୁହେଁ',
  'landing.whySubtitle': 'ଏକ କେନ୍ଦ୍ର ସରକାରୀ ପୋର୍ଟାଲ ପୂର୍ବରୁ ହଜାର ହଜାର ଯୋଜନା ତାଲିକାଭୁକ୍ତ କରିଛି। ସ୍କିମସେତୁ ଏହାର ସ୍ଥାନ ନେବାକୁ ଚେଷ୍ଟା କରେ ନାହିଁ — ଏହା ଗୋଟିଏ କାମ କରେ ଯାହା ଏକ ତାଲିକା କରିପାରିବ ନାହିଁ: ଏକ ନିର୍ଦ୍ଦିଷ୍ଟ ଯୋଜନା ଆପଣଙ୍କ ପାଇଁ କାହିଁକି ଉପଯୁକ୍ତ କିମ୍ବା ନୁହେଁ ତାହା ସଠିକ୍ ଭାବେ ଦେଖାଇବା।',
  'landing.why1Title': 'ସ୍କୋର ଯାହା ନିଜକୁ ନିଜେ ବ୍ୟାଖ୍ୟା କରେ',
  'landing.why1Desc': 'ପ୍ରତ୍ୟେକ ମେଳ ଠିକ୍ କେଉଁ ମାନଦଣ୍ଡ ପୂରଣ ହେଲା, ଛାଡ଼ି ଗଲା, କିମ୍ବା ବିଫଳ ହେଲା ତାହା ଦେଖାଏ — ବର୍ଗ, ଲିଙ୍ଗ, ରାଜ୍ୟ, କ୍ଷେତ୍ର, ବ୍ୟବସାୟ ପର୍ଯ୍ୟାୟ, ପ୍ରଥମ ଥର ଉଦ୍ୟୋଗୀ ସ୍ଥିତି, ଏବଂ ଆୟ — ତାଲିକାରେ କେବଳ ଏକ ନାମ ନୁହେଁ।',
  'landing.why2Title': 'ଏକ ମାର୍ଗଦର୍ଶିତ ପଥ, ସନ୍ଧାନ ବାକ୍ସ ନୁହେଁ',
  'landing.why2Desc': 'ଏକ ଛୋଟ ମୂଲ୍ୟାୟନ ଆପଣଙ୍କ ପରିସ୍ଥିତିକୁ ଥରେ ବୁଝେ, ତାପରେ ତାହା ଆଧାରରେ ପ୍ରତ୍ୟେକ ଯୋଜନାକୁ ର‌୍ୟାଙ୍କ କରେ — ହଜାର ହଜାର ମଧ୍ୟରୁ କେଉଁଟି ଦେଖିବାକୁ ହେବ ତାହା ଆପଣ ପୂର୍ବରୁ ଜାଣିଥିବେ ବୋଲି ଆଶା ନକରି।',
  'landing.why3Title': 'ଆପଣଙ୍କ ବ୍ୟବସାୟ ଚାରିପାଖରେ ତିଆରି, କେବଳ ଆପଣ କିଏ ତାହା ଉପରେ ନୁହେଁ',
  'landing.why3Desc': 'ମେଳ ଆପଣଙ୍କ ବ୍ୟବସାୟ କ୍ଷେତ୍ର, ପର୍ଯ୍ୟାୟ, ଏବଂ ପ୍ରଥମ ଥର ଉଦ୍ୟୋଗୀ ସ୍ଥିତିକୁ ମଧ୍ୟ ବିଚାର କରେ — କେବଳ ଜନସଂଖ୍ୟା ଯୋଗ୍ୟତା ନୁହେଁ — ଯାହା ଫଳରେ ଫଳାଫଳ ଦେଖାଇବ ଆପଣଙ୍କ ଉଦ୍ୟମ ପ୍ରକୃତରେ କେଉଁଠାରେ ଛିଡ଼ା ହୋଇଛି।',
  'landing.why4Title': 'ଇଣ୍ଟରନେଟ୍ ବିନା ମଧ୍ୟ କାମ କରେ',
  'landing.why4Desc': 'ଏକ ଆପ୍ ଭାବରେ ଇନଷ୍ଟଲ୍ କରାଯାଇପାରିବ ଏବଂ ଅଫଲାଇନ୍ ବ୍ୟବହାର ପାଇଁ ସାଇତି ରଖାଯାଏ, ଯାହା ଫଳରେ ସାଇତିଥିବା ମୂଲ୍ୟାୟନ ଏବଂ ଦେଖିଥିବା ଯୋଜନାଗୁଡ଼ିକ ସିଗ୍ନାଲ୍ ବିନା ମଧ୍ୟ ଉପଲବ୍ଧ ରହିବ।',
  'landing.why5Title': '୧୨ଟି ଭାରତୀୟ ଭାଷାରେ, ସମ୍ପୂର୍ଣ୍ଣ ଭାବରେ',
  'landing.why5Desc': 'ସମ୍ପୂର୍ଣ୍ଣ ମୂଲ୍ୟାୟନ, ଫଳାଫଳ, ଏବଂ ବ୍ୟାଖ୍ୟା ଅନୁବାଦ କରାଯାଇଛି — କେବଳ ପୃଷ୍ଠା ଶୀର୍ଷକ ଏବଂ ବଟନ୍ ନୁହେଁ।',
  'landing.whyHonestNote': 'ସ୍କିମସେତୁ ବର୍ତ୍ତମାନ {count}ଟି ହାତରେ ଯାଞ୍ଚ ହୋଇଥିବା ଯୋଜନାକୁ କଭର୍ କରେ — ସରକାରଙ୍କ ନିଜ ପୋର୍ଟାଲରେ ଥିବା ହଜାର ହଜାରର ଏକ ଛୋଟ ଅଂଶ। ଏହା ଏକ ଇଚ୍ଛାକୃତ ସମାଧାନ: ଏଠାରେ ପ୍ରତ୍ୟେକ ଯୋଜନାକୁ ବଡ଼ ପରିମାଣରେ ସଂଗ୍ରହ କରିବା ପରିବର୍ତ୍ତେ ଏକ ପ୍ରକୃତ ସରକାରୀ ଉତ୍ସ ବିରୁଦ୍ଧରେ ପୃଥକ ଭାବେ ଯାଞ୍ଚ କରାଯାଇଛି। ଆପାତତଃ, ପ୍ରସାର ଅପେକ୍ଷା ଗଭୀରତା।',

  'landing.ctaBandTitle': 'ଆପଣଙ୍କର ଯୋଜନା ଖୋଜିବାକୁ ପ୍ରସ୍ତୁତ?',
  'landing.ctaBandSubtitle': 'ଏକ ସଂକ୍ଷିପ୍ତ ମୂଲ୍ୟାୟନ ସମ୍ପୂର୍ଣ୍ଣ କରନ୍ତୁ ଏବଂ ମିନିଟ୍ ମଧ୍ୟରେ ବ୍ୟକ୍ତିଗତ, ବ୍ୟାଖ୍ୟାତ ଯୋଜନା ସୁପାରିଶ ପାଆନ୍ତୁ।',
  'landing.ctaBandButton': 'ମୂଲ୍ୟାୟନ ଆରମ୍ଭ କରନ୍ତୁ',

  'footer.blurb':
    'ଏକ ନିୟମ-ଆଧାରିତ ପ୍ଲାଟଫର୍ମ ଯାହା ପ୍ରାନ୍ତିକ ଉଦ୍ୟୋଗୀଙ୍କୁ ସେମାନଙ୍କର ବ୍ୟବସାୟ ପ୍ରୋଫାଇଲ୍, ଯୋଗ୍ୟତା ଏବଂ ଆବଶ୍ୟକତା ଆଧାରରେ ପ୍ରାସଙ୍ଗିକ ସରକାରୀ ଯୋଜନା ସହିତ ଯୋଡ଼େ।',
  'footer.builtFor': 'ସ୍ମାର୍ଟ ଇଣ୍ଡିଆ ହ୍ୟାକାଥନ୍ — SIH26092 ପାଇଁ ତିଆରି। ଏହା ପ୍ରଦର୍ଶନ ଉଦ୍ଦେଶ୍ୟରେ ଏକ ପ୍ରୋଟୋଟାଇପ୍।',
  'footer.platformHeading': 'ପ୍ଲାଟଫର୍ମ',
  'footer.importantHeading': 'ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ',
  'footer.importantNote1': 'ସୁପାରିଶଗୁଡ଼ିକ ନିୟମ-ଆଧାରିତ, ସରକାରୀ ନୁହେଁ।',
  'footer.importantNote2': 'ସର୍ବଦା ସରକାରୀ ଯୋଜନା ଉତ୍ସରେ ଯାଞ୍ଚ କରନ୍ତୁ।',
  'footer.importantNote3': 'କୌଣସି ସରକାରୀ ସଂସ୍ଥା ସହିତ ସମ୍ପୃକ୍ତ ନୁହେଁ।',
  'footer.copyright': '© {year} SchemeSetu — SIH26092 ପ୍ରୋଟୋଟାଇପ୍। ଏହା କୌଣସି ସରକାରୀ ପୋର୍ଟାଲ ନୁହେଁ।',
  'nav.institutions': 'ଅଂଶୀଦାର',
  'nav.emiCalculator': 'EMI କାଲକୁଲେଟର',
  'nav.toolsMenu': 'ଉପକରଣ',
  'nav.moreMenu': 'ଅଧିକ',
  'institutions.title': 'ଏହି ଯୋଜନାଗୁଡ଼ିକ କିଏ ଚଳାଏ',
  'institutions.subtitle':
    'ଏହି ଡାଟାସେଟରେ ଥିବା ପ୍ରତ୍ୟେକ ଯୋଜନା ପରିଚାଳନା କରୁଥିବା ପ୍ରକୃତ ସରକାରୀ ସଂସ୍ଥା ଏବଂ ନିଗମଗୁଡ଼ିକୁ ଦେଖନ୍ତୁ — ଏହା କୌଣସି ଶାଖା ଲୋକେଟର ନୁହେଁ, କେବଳ କାହା ପାଖକୁ ଯିବେ ତାହାର ସାଚ୍ଚା ସୂଚନା।',
  'institutions.searchPlaceholder': 'ସଂସ୍ଥା କିମ୍ବା ଯୋଜନା ଖୋଜନ୍ତୁ…',
