  'emi.breakdownAria': 'ମୂଳଧନ ମୋଟ ଦେୟର {principalPct}% ଏବଂ ସୁଧ {interestPct}%',
  'emi.legendPrincipal': 'ମୂଳଧନ',
  'emi.legendInterest': 'ସୁଧ',
  'emi.invalidInputs': 'ଆପଣଙ୍କର EMI ଦେଖିବାକୁ ଏକ ବୈଧ ଋଣ ରାଶି ଏବଂ ଅବଧି ଦିଅନ୍ତୁ।',
  'emi.disclaimer':
    'ଏହା ଏକ ସାଧାରଣ ଆକଳନ। ପ୍ରକୃତ ସୁଧ ହାର ଏବଂ ସର୍ତ୍ତାବଳୀ ଋଣଦାତା ବ୍ୟାଙ୍କ କିମ୍ବା NBFC ଦ୍ୱାରା ସ୍ଥିର ହୁଏ ଏବଂ ଯୋଜନା, ଆବେଦନକାରୀ ଏବଂ ଶାଖା ଅନୁସାରେ ଭିନ୍ନ ହୁଏ — ସର୍ବଦା ଋଣଦାତାଙ୍କ ସହିତ ନିଶ୍ଚିତ କରନ୍ତୁ।',
  'emi.pageTitle': 'EMI କାଲକୁଲେଟର',
  'emi.pageSubtitle': 'ଏହା କୌଣସି ନିର୍ଦ୍ଦିଷ୍ଟ ଯୋଜନା ସହିତ ସମ୍ପୃକ୍ତ ନୁହେଁ — ମାସିକ କିସ୍ତି ଆକଳନ କରିବାକୁ ଆପଣଙ୍କର ନିଜସ୍ୱ ସଂଖ୍ୟା ଦିଅନ୍ତୁ।',
  'offline.title': 'ଆପଣ ଅଫଲାଇନ୍ ଅଛନ୍ତି',
  'offline.body':
    'ଏହି ପୃଷ୍ଠା ଏପର୍ଯ୍ୟନ୍ତ ସାଇତି ହୋଇନାହିଁ। ଏହାକୁ ଲୋଡ୍ କରିବାକୁ ପୁନଃ ସଂଯୋଗ କରନ୍ତୁ, କିମ୍ବା ପୂର୍ବରୁ ଖୋଲିଥିବା କୌଣସି ପୃଷ୍ଠା ଦେଖନ୍ତୁ — ଏହା ଅଫଲାଇନ୍‌ରେ ମଧ୍ୟ କାମ କରିବ।',
  'pwa.install': 'ଆପ୍ ଇନଷ୍ଟଲ୍ କରନ୍ତୁ',
  'pwa.installed': 'ଇନଷ୍ଟଲ୍ ହୋଇଗଲା',
  'error.title': 'କିଛି ଭୁଲ ହୋଇଗଲା',
  'error.body':
    'ଏହି ପୃଷ୍ଠାରେ ଏକ ଅପ୍ରତ୍ୟାଶିତ ତ୍ରୁଟି ଘଟିଛି। ଆପଣ ପୁଣି ଚେଷ୍ଟା କରିପାରିବେ, କିମ୍ବା ମୁଖ୍ୟପୃଷ୍ଠାକୁ ଫେରିଯାଇପାରିବେ — ଆପ୍‌ର ବାକି ଅଂଶ ପ୍ରଭାବିତ ହୋଇନାହିଁ।',
  'error.startOver': 'ପୁଣି ଆରମ୍ଭ କରନ୍ତୁ',
  'error.goHome': 'ମୁଖ୍ୟପୃଷ୍ଠାକୁ ଯାଆନ୍ତୁ',
  'notFound.title': 'ପୃଷ୍ଠା ମିଳିଲା ନାହିଁ',
  'notFound.body': 'ଏହି ପ୍ରୋଟୋଟାଇପରେ ଏହି ପୃଷ୍ଠା ନାହିଁ।',
  'a11y.skipToContent': 'ମୁଖ୍ୟ ବିଷୟବସ୍ତୁକୁ ଯାଆନ୍ତୁ',
  'dataConfidence.label': 'ଉତ୍ସ ସମ୍ବନ୍ଧୀୟ ଟିପ୍ପଣୀ:',
  'machineTranslation.title': 'ଯାନ୍ତ୍ରିକ-ଅନୁବାଦିତ:',
  'machineTranslation.body':
    'ଏହି ଭାଷାକୁ ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ମାତୃଭାଷୀ ଦ୍ୱାରା ସମୀକ୍ଷା କରାଯାଇ ନାହିଁ, ତେଣୁ କିଛି ଶବ୍ଦ ଅସଠିକ ହୋଇପାରେ। ସବୁଠାରୁ ସଠିକ ସୂଚନା ପାଇଁ ଇଂରାଜୀ କିମ୍ବା ହିନ୍ଦୀକୁ ବଦଳାନ୍ତୁ।',
