  'assessment.privacyNote': 'സ്വകാര്യത: നിങ്ങളുടെ ഉത്തരങ്ങൾ ഈ ഉപകരണത്തിൽ തന്നെ സംരക്ഷിക്കപ്പെടുന്നു (ഈ ബ്രൗസറുമായി മാത്രം ബന്ധിപ്പിച്ച ഒരു സ്വകാര്യ ബാക്കപ്പും ഉണ്ടാകാം), അതിനാൽ നിങ്ങൾക്ക് പിന്നീട് തുടരാം. അനുയോജ്യമായ പദ്ധതികൾ കണ്ടെത്താൻ മാത്രമാണ് ഇവ ഉപയോഗിക്കുന്നത്. “{startOver}” ഇവ മായ്ക്കുന്നു.',

