  'checklist.step.upload-documents': 'രേഖകൾ അപ്‌ലോഡ് ചെയ്യുക',
  'checklist.step.submit-track': 'സമർപ്പിച്ച് ട്രാക്ക് ചെയ്യുക',
  'checklist.detail.check-eligibility':
    'ഔദ്യോഗിക ഉറവിടത്തിൽ നിങ്ങൾ ഈ പദ്ധതിയുടെ യോഗ്യതാ നിയമങ്ങൾ പാലിക്കുന്നുവെന്ന് സ്ഥിരീകരിക്കുക — ഈ പേജിൽ കാണിച്ചിരിക്കുന്ന പൊരുത്തം ഒരു ലളിതമായ പ്രോട്ടോടൈപ്പ് കണക്കാക്കലാണ്, അന്തിമ തീരുമാനമല്ല.',
  'checklist.detail.prepare-documents-fallback':
    'ഈ പ്രോട്ടോടൈപ്പിൽ പദ്ധതി-നിർദ്ദിഷ്ട രേഖകൾ ഇതുവരെ പട്ടികപ്പെടുത്തിയിട്ടില്ല — നിലവിലെ പട്ടികയ്ക്കായി താഴെയുള്ള ഔദ്യോഗിക ഉറവിടം പരിശോധിക്കുക.',
  'checklist.detail.visit-portal-fallback': 'ഈ എൻട്രിക്ക് ഔദ്യോഗിക ഉറവിട ലിങ്ക് രേഖപ്പെടുത്തിയിട്ടില്ല.',
  'checklist.detail.register-login':
    'മിക്ക പോർട്ടലുകൾക്കും ഒരു അക്കൗണ്ട് അല്ലെങ്കിൽ ലോഗിൻ ആവശ്യമാണ്, പലപ്പോഴും ആധാർ അല്ലെങ്കിൽ ബിസിനസ് രജിസ്ട്രേഷനുമായി ബന്ധപ്പെട്ടത്.',
  'checklist.detail.complete-application-fallback':
    'ഈ പ്രോട്ടോടൈപ്പിൽ പദ്ധതി-നിർദ്ദിഷ്ട അപേക്ഷാ ഘട്ടങ്ങൾ ഇതുവരെ പട്ടികപ്പെടുത്തിയിട്ടില്ല — ഔദ്യോഗിക പോർട്ടൽ നിങ്ങളെ അതിന്റെ സ്വന്തം പ്രക്രിയയിലൂടെ നയിക്കും.',
  'checklist.detail.upload-documents': 'പോർട്ടൽ ആവശ്യപ്പെടുന്ന ഫോർമാറ്റിലും വലുപ്പത്തിലും രേഖകൾ അപ്‌ലോഡ് ചെയ്യുക.',
  'checklist.detail.submit-track': 'അപേക്ഷ സമർപ്പിച്ച് പോർട്ടൽ നൽകുന്ന ഏതെങ്കിലും റഫറൻസ് അല്ലെങ്കിൽ ട്രാക്കിംഗ് നമ്പർ സേവ് ചെയ്യുക.',

