  'saved.subtitle': 'നിങ്ങൾ പിന്നീട് കാണാനോ അപേക്ഷിക്കാനോ ബുക്ക്മാർക്ക് ചെയ്ത പദ്ധതികൾ.',
  'saved.emptyTitle': 'ഇതുവരെ പദ്ധതികളൊന്നും സേവ് ചെയ്തിട്ടില്ല',
  'saved.emptyBody': 'നിങ്ങളുടെ ശുപാർശകളിൽ നിന്നോ പദ്ധതി ബ്രൗസറിൽ നിന്നോ ഒരു പദ്ധതി ബുക്ക്മാർക്ക് ചെയ്യുക, അത് ഇവിടെ ദൃശ്യമാകും.',
  'saved.browseSchemes': 'എല്ലാ പദ്ധതികളും ബ്രൗസ് ചെയ്യുക',
  'saved.needsProfile': 'നിങ്ങളുടെ സേവ് ചെയ്ത പദ്ധതികൾക്കായി വ്യക്തിഗതമാക്കിയ പൊരുത്ത സ്കോർ കാണാൻ നിങ്ങളുടെ വിലയിരുത്തൽ പൂർത്തിയാക്കുക.',
