  'browser.subtitle': '{count} സർക്കാർ പദ്ധതികളുടെ മുഴുവൻ ഡാറ്റാസെറ്റും തിരയുകയോ ഫിൽട്ടർ ചെയ്യുകയോ ചെയ്യുക — വിലയിരുത്തൽ ആവശ്യമില്ല.',
