  'landing.trustEyebrow': 'ഇത് എന്തുകൊണ്ട് വിശ്വസനീയമാണ്',
  'landing.trustSectionTitle': 'വിശ്വസിക്കാൻ യോഗ്യമായി നിർമ്മിച്ചത്',
  'landing.trust4Title': 'ലളിതമായ ഭാഷയിലുള്ള വിശദീകരണങ്ങൾ',
  'landing.trust4Desc': 'സങ്കീർണ്ണമായ സർക്കാർ പദപ്രയോഗങ്ങളില്ല — ഓരോ പൊരുത്തത്തിനും എന്തുകൊണ്ടെന്നതിന്റെ ലളിതമായ വിശദീകരണം ലഭിക്കും.',

  'landing.audienceEyebrow': 'ആർക്കൊക്കെ പ്രയോജനം ലഭിക്കും',
  'landing.audienceTitle': 'പാർശ്വവൽക്കരിക്കപ്പെട്ടവർക്കും ആദ്യമായി സംരംഭം തുടങ്ങുന്നവർക്കും വേണ്ടി നിർമ്മിച്ചത്',
