  'landing.eyebrow': 'SIH26092 · প্ৰ\'টোটাইপ',
  'landing.readInLabel': 'ইয়াত পঢ়ক:',
  'landing.heroTitle': 'আপুনি প্ৰকৃততে যোগ্য হোৱা চৰকাৰী আঁচনিসমূহ বিচাৰি উলিয়াওক',
  'landing.heroSubtitle': 'মহিলা, SC/ST, OBC, গ্ৰাম্য, নিম্ন আয়ৰ আৰু নতুন উদ্যোগীসকলৰ বাবে সাজি উলিওৱা। এটা চমু প্ৰ\'ফাইল পূৰণ কৰক, আৰু এখন স্বচ্ছ নিয়মভিত্তিক মিলোৱা ইঞ্জিনৰ জৰিয়তে শ্ৰেণীবদ্ধ, ব্যাখ্যাযোগ্য আঁচনি চুপাৰিছ লাভ কৰক — কোনো চেটবটে আপোনাৰ হৈ অনুমান কৰা নাই।',
