  'landing.step1Title': '1. আপোনাৰ প্ৰ\'ফাইল দিয়ক',
  'landing.step1Desc': 'শ্ৰেণী, লিংগ, ৰাজ্য, ক্ষেত্ৰ, ব্যৱসায়ৰ পৰ্যায়, আৰু কেইটামান দ্ৰুত যোগ্যতা সম্পৰ্কীয় প্ৰশ্ন।',
