  'landing.step2Desc': 'এটা স্বচ্ছ, নিৰ্ধাৰিত স্ক\'ৰিং ইঞ্জিনে আপোনাৰ প্ৰ\'ফাইলক প্ৰতিটো আঁচনিৰ সৈতে পৰীক্ষা কৰে — কোনো অনুমান নাই।',
