  'disclaimer.title': 'নিয়মভিত্তিক চুপাৰিছ, কোনো চৰকাৰী সিদ্ধান্ত নহয়।',
  'disclaimer.body': 'এইটো এটা হেকাথন প্ৰ\'টোটাইপ (SIH26092)। আবেদন কৰাৰ আগতে চূড়ান্ত যোগ্যতা, সুবিধা, প্ৰয়োজনীয় নথি-পত্ৰ আৰু আবেদনৰ পদক্ষেপ সদায় আঁচনিৰ চৰকাৰী উৎসত সত্যাপন কৰক।',
  'methodology.title': 'এইবোৰ নিয়মভিত্তিক মিল',
  'methodology.body': 'আপুনি উত্তৰ দিয়া সাতটা বিষয়ৰ ভিত্তিত গণনা কৰা হৈছে: শ্ৰেণী, লিংগ, ৰাজ্য, ক্ষেত্ৰ, ব্যৱসায়ৰ পৰ্যায়, প্ৰথমবাৰৰ উদ্যোগী হয় নে নাই, আৰু আয় (যদি দিয়া হৈছে)। আপুনি দিয়া আন তথ্য, যেনে ব্যৱসায়ৰ প্ৰয়োজন, টাৰ্নঅভাৰ, বা তহবিলৰ প্ৰয়োজনীয়তা, ভৱিষ্যতৰ নিৰ্দেশনা সুবিধাৰ বাবে সংৰক্ষিত থাকে, কিন্তু এতিয়াও এই স্ক\'ৰক প্ৰভাৱিত নকৰে।',
  'lowMatch.title': 'এতিয়াও এইবোৰৰ কোনোটোৱেই টান মিল নহয়',
  'lowMatch.body': 'আপুনি দিয়া তথ্যৰ ভিত্তিত, তলৰ আঁচনিবোৰ আপোনাৰ প্ৰ\'ফাইলৰ সৈতে টানকৈ নিমিলে। ইয়াৰ অৰ্থ এইটো নহয় যে একো উপলব্ধ নাই — আপোনাৰ শ্ৰেণী, ৰাজ্য, ক্ষেত্ৰ আৰু ব্যৱসায়ৰ পৰ্যায় পুনৰ পৰীক্ষা কৰক, কাৰণ এটা সৰু শুধৰণিয়ে ফলাফল সলনি কৰিব পাৰে। ইতিমধ্যে তলত তালিকাভুক্ত আঁচনিবোৰ পঢ়ি চোৱাও উপকাৰী হ\'ব পাৰে।',
