  'landing.feature6Desc': 'যিকোনো সময়ত সম্পূৰ্ণ আঁচনি তালিকা সন্ধান আৰু ফিল্টাৰ কৰক — কোনো প্ৰ\'ফাইলৰ প্ৰয়োজন নাই।',
  'landing.whyEyebrow': 'কিয় স্কিমসেতু',
  'landing.whyTitle': 'এটা কামৰ বাবে তৈয়াৰ, প্ৰতিটো আঁচনিৰ বাবে নহয়',
  'landing.whySubtitle': 'এখন কেন্দ্ৰীয় চৰকাৰী পৰ্টেলে ইতিমধ্যে হাজাৰ হাজাৰ আঁচনি তালিকাভুক্ত কৰিছে। স্কিমসেতুৱে ইয়াৰ ঠাই লবলৈ চেষ্টা নকৰে — ই এটা কাম কৰে যিটো এখন তালিকাই কৰিব নোৱাৰে: এটা নিৰ্দিষ্ট আঁচনি আপোনাৰ বাবে কিয় উপযুক্ত বা নহয় সেয়া সঠিকভাৱে দেখুওৱা।',
  'landing.why1Title': 'নিজেই নিজকে ব্যাখ্যা কৰা স্ক\'ৰ',
  'landing.why1Desc': 'প্ৰতিটো মিলে ঠিক কি মাপকাঠী পূৰণ হ\'ল, বাদ পৰিল, বা বিফল হ\'ল দেখুৱায় — শ্ৰেণী, লিঙ্গ, ৰাজ্য, খণ্ড, ব্যৱসায়িক পৰ্যায়, প্ৰথমবাৰৰ উদ্যোগী অৱস্থা, আৰু আয় — তালিকাত কেৱল এটা নামহে নহয়।',
  'landing.why2Title': 'এটা পথপ্ৰদৰ্শিত পথ, সন্ধান বাকচ নহয়',
  'landing.why2Desc': 'এটা চুটি মূল্যায়নে আপোনাৰ পৰিস্থিতি এবাৰ বুজি লয়, তাৰ পিছত তাৰ ভিত্তিত প্ৰতিটো আঁচনিক ৰেংক কৰে — হাজাৰ হাজাৰৰ মাজত কোনটো চাব লাগে সেয়া আপুনি আগতেই জানিব লাগে বুলি আশা নকৰাকৈ।',
  'landing.why3Title': 'আপোনাৰ ব্যৱসায়ৰ চাৰিওফালে তৈয়াৰ, কেৱল আপুনি কোন সেয়া নহয়',
  'landing.why3Desc': 'মিলবোৰে আপোনাৰ ব্যৱসায়িক খণ্ড, পৰ্যায়, আৰু প্ৰথমবাৰৰ উদ্যোগী অৱস্থাকো বিবেচনা কৰে — কেৱল জনসংখ্যাগত যোগ্যতা নহয় — যাতে ফলাফলে আপোনাৰ উদ্যম বাস্তৱত ক\'ত থিয় দি আছে দেখুৱায়।',
  'landing.why4Title': 'ইণ্টাৰনেট নোহোৱাকৈও কাম কৰে',
  'landing.why4Desc': 'এটা এপ হিচাপে ইনষ্টল কৰিব পাৰি আৰু অফলাইন ব্যৱহাৰৰ বাবে সংৰক্ষণ কৰি ৰখা হয়, যাতে সংৰক্ষণ কৰা মূল্যায়ন আৰু চোৱা আঁচনিবোৰ ছিগনেল নোহোৱাকৈও উপলব্ধ থাকে।',
