  'landing.why5Desc': 'সম্পূৰ্ণ মূল্যায়ন, ফলাফল, আৰু ব্যাখ্যা অনুবাদ কৰা হৈছে — কেৱল পৃষ্ঠাৰ শিৰোনাম আৰু বুটামহে নহয়।',
  'landing.whyHonestNote': 'স্কিমসেতুৱে বৰ্তমান {count}টা হাতেৰে সত্যাপিত আঁচনি সামৰি লৈছে — চৰকাৰৰ নিজৰ পৰ্টেলত থকা হাজাৰ হাজাৰৰ এটা সৰু অংশ। এইটো এটা ইচ্ছাকৃত সমঝোতা: ইয়াত প্ৰতিটো আঁচনি ডাঙৰ পৰিসৰত সংগ্ৰহ কৰাৰ পৰিৱৰ্তে এটা প্ৰকৃত চৰকাৰী উৎসৰ বিপৰীতে পৃথকভাৱে পৰীক্ষা কৰা হৈছে। আপাততঃ, বিস্তাৰতকৈ গভীৰতা।',
